// MAIN APP
// ═══════════════════════════════════════════════════════════════════════
export default function Betterway() {
  const [lang, setLang] = useState(detectLang);
  const switchLang = () => setLang((l) => (l === 'pl' ? 'en' : 'pl'));
  const t = I18N[lang];
  const questions = lang === 'en' ? QUESTIONS_EN : QUESTIONS_PL;
  const encouragements = lang === 'en' ? ENCOURAGEMENTS_EN : ENCOURAGEMENTS_PL;
  const types = lang === 'en' ? TYPES_EN : TYPES_PL;

  const [stage, setStage] = useState("landing");
  const [questionIdx, setQuestionIdx] = useState(0);
  const [answers, setAnswers] = useState({});
  const [showEncouragement, setShowEncouragement] = useState(false);

  const handleStart = () => setStage("quiz");

  const handleAnswer = (questionId, value) => {
    setAnswers((prev) => ({ ...prev, [questionId]: value }));

    if (questionIdx === questions.length - 1) {
      setStage("diagnosis");
      return;
    }

    setShowEncouragement(true);
    setTimeout(() => {
      setShowEncouragement(false);
      setQuestionIdx((i) => i + 1);
    }, 900);
  };

  const handleReveal = () => setStage("reveal");

  const handleRestart = () => {
    setStage("landing");
    setQuestionIdx(0);
    setAnswers({});
    setShowEncouragement(false);
    window.scrollTo({ top: 0, behavior: "instant" });
  };

  return (
    <>
      <FontsAndStyles />
      <div className="bw-root">
        <AnimatePresence mode="wait">
          {stage === "landing" && <Landing key="l" onStart={handleStart} t={t} onSwitchLang={switchLang} />}
          {stage === "quiz" && (
            <Quiz
              key="q"
              questionIdx={questionIdx}
              answers={answers}
              onAnswer={handleAnswer}
              showEncouragement={showEncouragement}
              questions={questions}
              encouragements={encouragements}
              t={t}
            />
          )}
          {stage === "diagnosis" && (
            <Diagnosis key="d" answers={answers} onReveal={handleReveal} types={types} t={t} />
          )}
          {stage === "reveal" && <Reveal key="r" answers={answers} onRestart={handleRestart} questions={questions} t={t} />}
        </AnimatePresence>
      </div>
    </>
  );
}

